!function(r){function e(e){for(var i,n,p=e[0],s=e[1],u=e[2],c=0,l=[];c<p.length;c++)n=p[c],Object.prototype.hasOwnProperty.call(a,n)&&a[n]&&l.push(a[n][0]),a[n]=0;for(i in s)Object.prototype.hasOwnProperty.call(s,i)&&(r[i]=s[i]);for(m&&m(e);l.length;)l.shift()();return o.push.apply(o,u||[]),t()}function t(){for(var r,e=0;e<o.length;e++){for(var t,n=o[e],p=!0,s=1;s<n.length;s++)t=n[s],0!==a[t]&&(p=!1);p&&(o.splice(e--,1),r=i(i.s=n[0]))}return r}function i(e){if(n[e])return n[e].exports;var t=n[e]={i:e,l:!1,exports:{}};return r[e].call(t.exports,t,t.exports,i),t.l=!0,t.exports}var n={},a={14:0},o=[];i.m=r,i.c=n,i.d=function(r,e,t){i.o(r,e)||Object.defineProperty(r,e,{enumerable:!0,get:t})},i.r=function(r){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(r,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(r,"__esModule",{value:!0})},i.t=function(r,e){if(1&e&&(r=i(r)),8&e)return r;if(4&e&&"object"==typeof r&&r&&r.__esModule)return r;var t=Object.create(null);if(i.r(t),Object.defineProperty(t,"default",{enumerable:!0,value:r}),2&e&&"string"!=typeof r)for(var n in r)i.d(t,n,function(e){return r[e]}.bind(null,n));return t},i.n=function(r){var e=r&&r.__esModule?function(){return r.default}:function(){return r};return i.d(e,"a",e),e},i.o=function(r,e){return Object.prototype.hasOwnProperty.call(r,e)},i.p="";var p=window.webpackJsonp=window.webpackJsonp||[],s=p.push.bind(p);p.push=e,p=p.slice();for(var u=0;u<p.length;u++)e(p[u]);var m=s;o.push([89,0]),t()}({89:function(r,e,t){"use strict";t.r(e);var i=t(0);Object(i.a)("us","army",t(90),t(1))},90:function(r){r.exports=JSON.parse('{"category":[{"name":"美国","link":"us_shortcut"},{"name":"陆战武器","link":"us_army"},{"name":"轻武器","link":"us_army#us_army_iw"}],"model":"美军火焰喷射器","description":"<h6>综述：</h6><p>二战中，美军装备的火焰喷射器有M1和M2型。M1型是在1941年定型，1942年开始生产并装备美军，但由于其射程、火焰杀伤力和可靠性都不理想，在1944年，美国通过对燃料的升级（用凝固汽油取代混合石油），大大提高了温度和射程，同时也提高了可靠性与实用性，并定型为M2型并在1944年7月太平洋战场的关岛首次投入战斗。M2型火焰喷射器对于歼灭坚守于洞窟阵地或是丛林之中的日军非常有效，是日本士兵非常恐惧的一种武器。</p><p>火焰喷射器在太平洋战争中发挥了巨大作用，是二战太平洋战场上一种极为有效的攻坚武器，大幅降低了美军的伤亡率，可以说在一定程度上加速了太平洋战争的胜利。</p>","part1title":"系列型号","part1description":"","part1content":[{"image":"imgs/us/army/us_army_iwFlamethrower_10.jpg","description":"<h6>M2型火焰喷射器</h6><p></p><p>基本技术数据：</p><p>喷射器重量：19.5公斤（无燃料），30.84公斤（带燃料）；</p><p>燃料供应方式：2罐2加仑汽油罐，1罐氮气罐；</p><p>射速：0.5加仑/秒；</p><p>最长喷射时间：7秒；</p><p>射程：19.96米（有效），40.23米（最大）；</p><p>操作人数：1人。</p>","caption":""}],"part2title":"战场上的美军火焰喷射器","part2description":"","part2content":[{"image":"imgs/us/army/us_army_iwFlamethrower_20.jpg","description":"（图左）身背M2型火焰喷射器的美军火焰喷射兵的身后装备：2瓶（大）汽油罐和1瓶（小）氮气罐。（图右）二战战场上美军第77步兵师一名身背M2型火焰喷射器的火焰喷射兵。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_21.jpg","description":"使用M2型火焰喷射器正在喷火的一名美军士兵。M2型火焰喷射器燃料采用了凝固汽油，其喷出的火焰温度高达1000℃，最大射程可超过40米，而且火柱还可以顺着工事、坑道的墙壁“拐弯”，或是撞在墙壁上产生飞溅，飞溅出的火焰可以在粘附物体上继续燃烧，使火焰杀伤能力得到极大加强。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_22.jpg","description":"二战战场上，一名身背M2型火焰喷射器的美军喷火兵正在加速跃向日军工事。在前线，喷火兵较其它兵种的士兵危险性更大。为了摧毁碉堡，需要近距离去靠近碉堡，因而极易受到日军枪击而导致伤亡，且暴露在外的燃料罐一旦被击中即会爆燃，因此在太平洋战争中，美军喷火兵的伤亡率是相当大的。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_23.jpg","description":"1944年6月，太平洋战场，塞班岛，一名美国海军陆战队的火焰喷射兵正拿着M2型火焰喷射器准备向日军开火。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_24.jpg","description":"1944年7月，太平洋战场塞班岛最北端马尔皮角，距日军司令部和日本人自杀的悬崖几百英尺处，四名美国海军陆战队第4师突击连士兵的合影，其中有两名拿着M2型火焰喷射器的火焰喷射兵。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_25.jpg","description":"1945年初，太平洋战场硫磺岛战役，美国海军陆战队一支火焰喷射分队正背着M2型火焰喷射器向前线运动。在太平洋战场的岛屿争夺战中，日军依托岛屿的复杂地形构筑了很多明碉暗堡，造成美军大量伤亡。在实战中，美军发现，用火焰喷射器摧毁这些碉堡和工事，杀伤躲在内部的日军，相对迫击炮和火箭筒效果会更好，因此，从1943年10月开始，美军为太平洋战区的每个师配备了更多的火焰喷射器，从过去的24具增加到60具。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_26.jpg","description":"1945年初，太平洋战场硫磺岛，美国海军陆战队的火焰喷射兵队正在用M2型火焰喷射器攻击日军碉堡。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_27.jpg","description":"绘画：二战太平洋战场，在小分队掩护下的一名美军美国海军陆战队的火焰喷射兵冲近日军地下工事，用M2型火焰喷射器从工事入口处向日军喷射火焰。火焰喷射器虽然威力强大，但因射程近、持续时间短，喷射时需要冒险迫近敌方工事，为了减少伤亡，通常会有一个小队负责压制和干扰敌人火力。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_28.jpg","description":"二战太平洋战场，一名正在使用M2型火焰喷射器向日军工事喷射火焰的美国海军陆战队士兵。通过高气压动力喷射出剧烈燃烧的油料，其高温能有效杀伤隐藏在坚固碉堡、工事、山洞或壕沟内的敌军，同时引燃堆放在内的武器弹药和装备物资。","caption":""},{"image":"imgs/us/army/us_army_iwFlamethrower_29.jpg","description":"绘画：二战太平洋战场，一名正在使用M2型火焰喷射器向日军工事喷射火焰的美国海军陆战队士兵。到了太平洋战争后期，美军对于火焰喷射器的使用可以说是炉火纯青了。","caption":""}]}')}});